def solve(arr):
    """Return length of longest strictly increasing subsequence.
    Handles non-integer elements by ignoring them.
    """
    import bisect
    if not arr:
        return 0
    tails = []
    for x in arr:
        if not isinstance(x, int):
            # skip non-integer values
            continue
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

