def solve(nums):
    # Patience sorting algorithm O(n log n)
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subsequence of length i+1
    for x in nums:
        # find position to replace in tails
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

