def solve(s: str) -> bool:
    """Return True if brackets in s are balanced and properly nested.
    Handles (), [], {} and ignores other characters.
    """
    stack = []
    opening = {'(': ')', '[': ']', '{': '}'}
    closing = set(opening.values())
    for ch in s:
        if ch in opening:
            stack.append(opening[ch])
        elif ch in closing:
            if not stack or stack.pop() != ch:
                return False
    return not stack

