def solve(matrix):
    if not matrix:
        return []
    # Determine dimensions; handle ragged rows by using min length for columns? We'll treat missing entries as absent.
    # We'll traverse bounds based on actual rows and columns per row, assuming rectangular as per spec.
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1
    result = []
    while top <= bottom and left <= right:
        # top row
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1
        # right column
        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1
        if top <= bottom:
            # bottom row
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1
        if left <= right:
            # left column
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1
    return result

