def solve(nums):
    """Return the next lexicographic permutation of the list of integers.
    For empty or single-element lists, return the list itself (or sorted, which is same).
    If the input is the highest permutation, return the sorted list.
    """
    if len(nums) <= 1:
        return nums[:]
    arr = nums[:]
    n = len(arr)
    i = n - 2
    while i >= 0 and arr[i] >= arr[i + 1]:
        i -= 1
    if i == -1:
        return sorted(arr)
    j = n - 1
    while arr[j] <= arr[i]:
        j -= 1
    arr[i], arr[j] = arr[j], arr[i]
    arr[i + 1:] = reversed(arr[i + 1:])
    return arr

